"""Whole-file CORDIC rotation and fixed-point interface lessons."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='CORDIC · 고정소수점·복소 평면 회전',
                     sections=sections, questions=questions))


add('lib/math/cordic.c', 'CORDIC 구현 전체: 시프트와 덧셈으로 좌표 회전하기',
    '각도를 작은 회전의 합으로 근사하여 코사인·사인 좌표를 얻습니다.',
    '초기 좌표는(39797,0)이고 누적 각도는0입니다. 목표와 누적 각도를 비교해 매 단계 ±atan(2^-iter) 방향으로 회전합니다. 곱셈 대신 좌표의 오른쪽 시프트를 사용하며18단계 뒤 사분면 부호를 복구합니다.',
    '입력 theta는 정수 도 단위이며 출력 i,q는2^16 배율의 근사 좌표입니다. 라디안이나 이미 스케일된 입력을 넘기는 인터페이스가 아닙니다.',
    [('전체 파일', 'Broadcom 저작권·허용 조건·면책문, module/cordic 헤더,18개 s32 arctan_table,cordic_calc_iq,공개 export,설명·작성자·Dual BSD/GPL 모듈 정보로 구성됩니다. 원문에 없는 SPDX 줄을 있다고 간주하지 않습니다.'),
     ('표와 이득 보정', '표는 atan(2^-i)를 도 단위로 바꾸고2^16배하여 반올림한18개 값입니다. 첫 값2949120은45*65536입니다. 시프트 회전은 크기를 sqrt(1+2^(-2i))배 늘리므로 초기 x를 약0.60725*65536인39797로 두어 전체 이득을 미리 보정합니다. 반복 중 별도 제곱근이나 삼각함수 호출은 없습니다.'),
     ('각도 정규화', '먼저 theta를 고정소수점으로 바꾸고 입력 부호 signtheta를 구합니다. ±180을 더한 뒤360으로 나머지를 취하고 같은180을 빼서 주기를 접습니다. 다음90도보다 크면180을 빼고,-90도보다 작으면180을 더하여 signx=-1로 표시합니다. 마지막에는 i와q 둘 다 이 부호를 곱하므로180도 회전 관계를 복원합니다.'),
     ('회전의 동시 갱신', 'theta>angle이면 새 i=옛 i-(옛 q>>iter),새 q=옛 q+(옛 i>>iter)입니다. 반대 분기는 각각 덧셈과 뺄셈을 뒤집습니다. valtmp로 i를 잠시 보관하여 q 계산이 옛 i를 사용하도록 합니다. 목표와 누적 각도가 같아도 else 분기로 작은 회전을 수행하므로0도 결과가 반드시 수학적으로 완벽한(65536,0)인 것은 아닙니다.'),
     ('종료와 오차', 'iter=0..17의 고정18회 반복이라 입력 크기에 따라 무제한 반복하지 않습니다. 상수 표 양자화·시프트 절단·유한 반복 때문에 근사 오차가 남습니다. i/65536은cos(theta),q/65536은sin(theta)에 대응합니다.90도 부근의 아주 작은 비영 i는 곧바로 함수 오류라는 뜻이 아닙니다.'),
     ('타입과 입력 범위', '정규화 전에 s32 고정소수점 시프트를 수행하므로 임의의 큰 s32 각도를 안전하게360으로 먼저 줄이는 함수가 아닙니다. 음수 시프트와 signed 우측 시프트는 커널의 컴파일러·타깃 관례도 고려해야 하며 그대로 가져온 코드가 모든 ISO C 환경에서 같은 의미라고 주장하지 않습니다. 검증한 입력 구간과 컴파일 조건을 명시합니다.'),
     ('문서와 실제 시그니처', '주석에는 coord 출력 인자가 언급되지만 실제 함수는 theta 하나를 받고 struct cordic_iq를 값으로 반환합니다. 출력 포인터는 없습니다. 주석을 코드의 실제 인터페이스와 대조하는 것도 오픈소스 읽기의 일부입니다.')],
    [('반복 중 valtmp가 필요한 이유는?', 'q 계산이 갱신 전 i를 사용하도록 하기 위해서다', 'i의 메모리를 동적으로 할당하기 위해서다', '회전 식의 두 좌표는 같은 이전 상태에서 계산해야 합니다. i를 먼저 덮으면 q에 새 i를 사용하는 다른 변환이 됩니다.'),
     ('표의 첫 값2949120은 어떤 각도인가?', '2^16배로 표현한45도', '2949120라디안', 'atan(1)=45도이고45*65536=2949120입니다. 입력과 표의 단위 및 스케일을 구분합니다.'),
     ('signx=-1이면 어느 좌표에 부호를 적용하는가?', 'i와q 둘 다', 'i만', '목표를180도 옮긴 뒤 되돌리므로cos와sin 모두 부호가 바뀝니다. 실제 마지막 두 곱셈도 이를 반영합니다.'),
     ('주석의 coord를 두 번째 인자로 전달해야 하는가?', '아니다. 함수는 구조체를 반환한다', '그렇다. 출력 포인터 인자가 선언되어 있다', '실제 시그니처는 struct cordic_iq cordic_calc_iq(s32 theta)입니다. 오래된 주석 문구보다 선언과 본문을 함께 확인해야 합니다.')])

add('include/linux/cordic.h', 'CORDIC 헤더 전체: 좌표 타입과 고정소수점 변환',
    '정수와 스케일된 정수를 구분하고 매크로의 평가·범위 조건을 읽습니다.',
    '초기 이득 보정값39797,소수부16비트,반복 횟수18을 정의합니다. CORDIC_FIXED와 CORDIC_FLOAT 변환, s32 i/q 구조체,각도 입력 함수 선언이 이어집니다.',
    'CORDIC_FLOAT라는 이름은 float 타입을 반환한다는 뜻이 아닙니다. 정수 시프트로 고정소수점 값을 가까운 정수로 반올림합니다.',
    [('파일 전체', 'Broadcom 저작권·허용 조건, __CORDIC_H_ guard,types.h 포함,상수3개,변환 매크로2개,구조체와 문서화된 함수 선언,#endif가 전부입니다. arctan 표와 회전 본문은 구현 파일에 있습니다.'),
     ('상수와 좌표', 'CORDIC_NUM_ITER는 CORDIC_PRECISION_SHIFT+2로18입니다. i는 in-phase 실수부,q는 quadrature 허수부입니다. 함수 문서는 이들이 각각cos와sin에 대응하며2^16 배율임을 명시합니다. 구조체에는 각도나 상태 코드 필드가 없습니다.'),
     ('변환과 반올림', 'CORDIC_FIXED(X)는 X를16비트 왼쪽 이동한 뒤 s32로 캐스트합니다. 뒤의 캐스트가 앞선 식의 오버플로나 유효하지 않은 시프트를 복구하지는 않습니다. CORDIC_FLOAT는 부호에 따라 절댓값 쪽에서 반올림한 뒤 부호를 붙이므로 표현 가능한 ±1.5는±2가 됩니다. 실제 부동소수점 연산은 없습니다.'),
     ('매크로 주의점', 'CORDIC_FLOAT는 조건과 선택된 분기에 X가 반복되어 나타나므로 X++ 같은 부수효과를 피해야 합니다. 가장 작은 signed 값의 부호 반전도 표현 범위를 확인해야 합니다. CORDIC_FIXED 입력과 함수 theta 입력의 단위를 혼동해 두 번 스케일하지 않습니다.'),
     ('정규화 계약의 범위', '문서는 -180..180 밖의 각도를 변환한다고 설명하지만 구현은 큰 값에 대한 시프트·덧셈 범위 검사 없이 먼저 스케일합니다. 제한 없는 s32 입력의 안전성 보장으로 확장하지 않습니다. coord가 출력 인자라는 문구도 실제 구조체 반환 선언과 구분합니다.')],
    [('CORDIC_FLOAT(98304)는 어떤 타입의 계산으로 어떤 값을 얻는가?', '정수 시프트로2를 얻는다', 'float 타입의1.5를 얻는다', '98304/65536=1.5를 가장 가까운 정수로 반올림합니다. 이름과 달리 float 변환이 아닙니다.'),
     ('CORDIC_FIXED의 마지막 s32 캐스트가 이전 시프트 문제를 모두 막는가?', '아니다. 시프트는 캐스트 전에 계산된다', '그렇다. 뒤에서 캐스트하면 앞선 계산도 안전해진다', '식의 평가 순서상 (X)<<16이 먼저입니다. 입력 타입과 유효 범위를 별도로 확인해야 합니다.'),
     ('CORDIC_FLOAT에 부수효과 있는 식을 전달해도 한 번만 평가되는가?', '아니다. X가 조건과 결과 식에 반복된다', '그렇다. 임시 변수에 저장한다', '매크로에는 임시 저장이 없습니다. 값을 변수에 먼저 계산해 전달해야 평가 횟수 문제를 피할 수 있습니다.')])
